class Solution {
public:
    bool isMatch(string s, string p) {
        int m = s.size(), n = p.size();
        vector<bool> dp(n + 1, false);
        dp[0] = true;
        for (int j = 1; j <= n; ++j) {
            if (p[j - 1] == '*') dp[j] = dp[j - 1];
        }
        for (int i = 1; i <= m; ++i) {
            bool diag = dp[0];
            dp[0] = false;
            for (int j = 1; j <= n; ++j) {
                bool temp = dp[j];
                if (p[j - 1] == '*') {
                    dp[j] = dp[j] || dp[j - 1];
                } else if (p[j - 1] == '?' || p[j - 1] == s[i - 1]) {
                    dp[j] = diag;
                } else {
                    dp[j] = false;
                }
                diag = temp;
            }
        }
        return dp[n];
    }
};

class Solution {
    public boolean isMatch(String s, String p) {
        int m = s.length(), n = p.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int j = 1; j <= n; j++) {
            if (p.charAt(j - 1) == '*') dp[j] = dp[j - 1];
        }
        for (int i = 1; i <= m; i++) {
            boolean diag = dp[0];
            dp[0] = false;
            for (int j = 1; j <= n; j++) {
                boolean temp = dp[j];
                if (p.charAt(j - 1) == '*') {
                    dp[j] = dp[j] || dp[j - 1];
                } else if (p.charAt(j - 1) == '?' || p.charAt(j - 1) == s.charAt(i - 1)) {
                    dp[j] = diag;
                } else {
                    dp[j] = false;
                }
                diag = temp;
            }
        }
        return dp[n];
    }
}

var isMatch = function(s, p) {
    const m = s.length, n = p.length;
    const dp = new Array(n + 1).fill(false);
    dp[0] = true;
    for (let j = 1; j <= n; j++) {
        if (p[j - 1] === '*') dp[j] = dp[j - 1];
    }
    for (let i = 1; i <= m; i++) {
        let diag = dp[0];
        dp[0] = false;
        for (let j = 1; j <= n; j++) {
            const temp = dp[j];
            if (p[j - 1] === '*') {
                dp[j] = dp[j] || dp[j - 1];
            } else if (p[j - 1] === '?' || p[j - 1] === s[i - 1]) {
                dp[j] = diag;
            } else {
                dp[j] = false;
            }
            diag = temp;
        }
    }
    return dp[n];
};
